//https://levelup.gitconnected.com/stencil-component-translations-4efc44018b1d
import browserLanguage from "./browserLang";

interface Translation {
	[key: string]: string;
}

interface Translations {
	en: Translation;
	ko: Translation;
	ja: Translation;
	zh: Translation;
}

const DEFAULT_LANGUAGE = "en" as const;
const SUPPORTED_LANGUAGES: string[] = ["en", "ko", "ja", "zh"];

const browserLang: string | undefined = browserLanguage();

export const internationalization = (
	translations: Translations,
	key: string,
	customLang?: "en" | "ja" | "ko" | "zn",
): string => {
	const lang: string | undefined = customLang || browserLang;
	return translations[
		lang !== undefined && SUPPORTED_LANGUAGES.includes(lang)
			? lang
			: DEFAULT_LANGUAGE
	][key];
};
